+        return operations == 0 && requests == 0;
+    }
+
+    @Override
+    public XContentBuilder toXContent(XContentBuilder builder, Params params) throws IOException {
+        builder.startObject();
+        builder.field("operations", operations);
+        builder.field("requests", requests);
+        builder.endObject();
+        return builder;
+    }
