+    private static Policy createPluginPolicy(String... pluginModules) {
+        return new Policy(
+            "plugin",
+            Arrays.stream(pluginModules)
+                .map(
+                    name -> new Scope(
+                        name,
+                        List.of(new FileEntitlement("/test/path", List.of(FileEntitlement.READ)), new CreateClassLoaderEntitlement())
